<script lang="ts">
  import {searchableSelect} from '#lib/client/searchable-select.ts';
 import type{DesignElement,DesignOperation}from'@schubert/contracts';import{contourParts}from'@schubert/geometry';
 let{stone,treatments=[],onchange}:{stone:Extract<DesignElement,{kind:'stone_piece'}>;treatments?:any[];onchange:(operations:DesignOperation[])=>void}=$props();
 let ringIndex=$state('0'),edgeIndex=$state('0'),ringProfile=$state('');
 const rings=$derived.by(()=>{let offset=0;return contourParts(stone.finishedContour).flatMap((part,p)=>[part.outer,...part.holes].map((edges,r)=>{const entry={edges,offset,label:`Bestandteil ${p+1} · ${r?'Ausschnitt '+r:'Außenkontur'}`};offset+=edges.length;return entry;}));}),ring=$derived(rings[Number(ringIndex)]??rings[0]),edge=$derived(ring?.edges[Number(edgeIndex)]??ring?.edges[0]),globalIndex=$derived((ring?.offset??0)+Math.min(Number(edgeIndex),Math.max(0,(ring?.edges.length??1)-1)));
 function set(indices:number[],versionId:string){onchange([{type:'set_stone_spec',elementId:stone.id,edgeTreatments:[...stone.edgeTreatments.filter(t=>!indices.includes(t.edgeIndex)),...(versionId?indices.map(edgeIndex=>({edgeIndex,treatmentVersionId:versionId})):[])]}]);}
</script>
<div class="edge-profile"><label>Konturbestandteil<select use:searchableSelect={ringIndex} bind:value={ringIndex} onchange={()=>edgeIndex='0'}>{#each rings as r,index}<option value={String(index)}>{r.label} · {r.edges.length} Kanten</option>{/each}</select></label>
 <label>Einzelkante<select use:searchableSelect={edgeIndex} bind:value={edgeIndex}>{#each ring?.edges??[] as e,index}<option value={String(index)}>Kante {index+1} · {e.kind==='circular_arc'?'Kreisbogen':'Gerade'}</option>{/each}</select></label>
 {#if edge}<p>Von {edge.from.xMm} / {edge.from.yMm} nach {edge.to.xMm} / {edge.to.yMm} mm</p>{/if}
 <label>Geprüftes Profil dieser Kante<select use:searchableSelect={stone.edgeTreatments.find(t=>t.edgeIndex===globalIndex)?.treatmentVersionId??''} value={stone.edgeTreatments.find(t=>t.edgeIndex===globalIndex)?.treatmentVersionId??''} onchange={event=>set([globalIndex],event.currentTarget.value)}><option value="">Keine Bearbeitung festgelegt</option>{#each treatments as treatment}<option value={treatment.id}>{treatment.name}</option>{/each}</select></label>
 <details><summary>Gesamten Konturring bearbeiten</summary><p>Ein freigegebenes Kantenprofil ausdrücklich allen Geraden und Bogensegmenten dieses Rings zuordnen.</p><label>Profil für den gesamten Ring<select use:searchableSelect={ringProfile} bind:value={ringProfile}><option value="">Alle Profilzuordnungen dieses Rings entfernen</option>{#each treatments as treatment}<option value={treatment.id}>{treatment.name}</option>{/each}</select></label><button class="btn small" onclick={()=>set((ring?.edges??[]).map((_,i)=>(ring?.offset??0)+i),ringProfile)}>Auf diesen Konturring anwenden</button></details>
 <p>{stone.edgeTreatments.length} Kanten mit konkretem Profilstand. Bei einer geänderten Kantenfolge müssen die Zuordnungen neu geprüft werden.</p>
</div>
<style>.edge-profile{font-size:13px}label{display:block;margin:14px 0;font-weight:550}select{display:block;width:100%;box-sizing:border-box;margin-top:7px;padding:9px;font:inherit;font-weight:400;color:inherit;background:var(--paper);border:1px solid var(--line);border-radius:4px;min-height:44px}.edge-profile p{font-size:12px;line-height:1.65;color:var(--muted);overflow-wrap:anywhere}details{border-top:1px solid var(--line);padding-top:15px;margin-top:15px}summary{cursor:pointer;line-height:1.6}@media(max-width:720px){select,.btn{min-height:48px;font-size:16px}}</style>
